POINTS_DISPLAY=true SURVIVAL_POINTS=0 SURVIVAL_POINTS_PLAYERS={}function AOD_Points_IncreaseTotalScore(points)SURVIVAL_POINTS=SURVIVAL_POINTS+points end function AOD_Points_DecreaseTotalScore(points)SURVIVAL_POINTS=SURVIVAL_POINTS-points end function AOD_Points_GetTotalScore()return SURVIVAL_POINTS end function AOD_Points_IncreaseTeamScore(ownerPlayer,points)local humanPlayers=Team_GetPlayers(0)local totalPlayers=#humanPlayers local ownerPoints=0 local otherPoints=0 if(totalPlayers>1)then ownerPoints=0.75*points otherPoints=0.25*points/(totalPlayers-1)else ownerPoints=points end for i,humanPlayer in ipairs(humanPlayers)do if(humanPlayer==ownerPlayer)then AOD_Points_IncreasePlayerScore(humanPlayer,ownerPoints)else AOD_Points_IncreasePlayerScore(humanPlayer,otherPoints)end
end end function AOD_Points_IncreasePlayerScore(player,points)
local playerId=Player_GetID(player)local playerPoints=SURVIVAL_POINTS_PLAYERS[playerId]or{["total"]=0,["available"]=0}playerPoints["total"]=playerPoints["total"]+points playerPoints["available"]=playerPoints["available"]+points SURVIVAL_POINTS_PLAYERS[playerId]=playerPoints end function AOD_Points_SpendPlayerScore(player,points)local playerId=Player_GetID(player)local playerPoints=SURVIVAL_POINTS_PLAYERS[playerId]or{["total"]=0,["available"]=0}playerPoints["available"]=playerPoints["available"]-points SURVIVAL_POINTS_PLAYERS[playerId]=playerPoints end function AOD_Points_GetPlayerScore(player)local playerId=Player_GetID(player)local playerPoints=SURVIVAL_POINTS_PLAYERS[playerId]or{["total"]=0,["available"]=0}return playerPoints["total"]end function AOD_Points_GetPlayerAvailableScore(player)local playerId=Player_GetID(player)local playerPoints=SURVIVAL_POINTS_PLAYERS[playerId]or{["total"]=0,["available"]=0}return playerPoints["available"]end function AOD_Points_InitScoreObjective()OBJECTIVES['aod_score']={OnStart=function()end,SetupUI=function()end,OnComplete=function()end,OnFail=function()end,IsComplete=function()return false end,Intel_Start=nil,Intel_Complete=nil,Intel_Fail=nil,Description=nil,TitleEnd=nil,TitleFail=nil,Type=OT_Primary,Title=Loc_FormatText(Util_CreateLocId(1337020),Loc_ConvertNumber(0))
}Objective_Register(OBJECTIVES['aod_score'])end function AOD_Points_UpdateScoreObjective(show,score)score=score or round(AOD_Points_GetTotalScore(),0)if(not Objective_IsStarted(OBJECTIVES["aod_score"]))then Objective_Start(OBJECTIVES['aod_score'],false)end Objective_UpdateText(OBJECTIVES["aod_score"],Loc_FormatText(Util_CreateLocId(1337020),Loc_ConvertNumber(score)),nil,show)
end AOD_POINT_CURRENT=1 function AOD_Points_ShowData()local i=1 local shown=false for playerId,playerPoints in pairs(SURVIVAL_POINTS_PLAYERS)do if(not shown and i==AOD_POINT_CURRENT)then local playerName=Player_GetDisplayName(Player_FromId(playerId))[1]
local eventCueText=Util_CreateLocString(playerName.." points available: "..round(playerPoints["available"],0).."/"..round(playerPoints["total"],0))
UI_CreateEventCue("Icons_abilities_ability_german_infantry_awareness","",eventCueText,eventCueText,5)AOD_POINT_CURRENT=AOD_POINT_CURRENT+1 shown=true end i=i+1 end if(AOD_POINT_CURRENT>=i)then AOD_POINT_CURRENT=1 end end
